// NewCreateRequestBody builds the HTTP request body from the payload of the
// "create" endpoint of the "organization" service.
func NewCreateRequestBody(p *organization.CreateOrganizationPayload) *CreateRequestBody {
	body := &CreateRequestBody{
		Name:               p.Name,
		LegalName:          p.LegalName,
		DisplayName:        p.DisplayName,
		OrganizationType:   string(p.OrganizationType),
		TaxID:              p.TaxID,
		RegistrationNumber: p.RegistrationNumber,
		IncorporationDate:  p.IncorporationDate,
		Jurisdiction:       p.Jurisdiction,
		Description:        p.Description,
		Website:            p.Website,
		Industry:           p.Industry,
		EmployeeCount:      p.EmployeeCount,
		ParentID:           p.ParentID,
	}
	if p.Addresses != nil {
		body.Addresses = make([]*AddressInfoRequestBody, len(p.Addresses))
		for i, val := range p.Addresses {
			body.Addresses[i] = marshalOrganizationAddressInfoToAddressInfoRequestBody(val)
		}
	}
	if p.Contacts != nil {
		body.Contacts = make([]*ContactInfoRequestBody, len(p.Contacts))
		for i, val := range p.Contacts {
			body.Contacts[i] = marshalOrganizationContactInfoToContactInfoRequestBody(val)
		}
	}
	if p.Settings != nil {
		body.Settings = marshalOrganizationOrganizationSettingsToOrganizationSettingsRequestBody(p.Settings)
	}
	return body
}

// NewUpdateRequestBody builds the HTTP request body from the payload of the
// "update" endpoint of the "organization" service.
func NewUpdateRequestBody(p *organization.UpdateOrganizationPayload) *UpdateRequestBody {
	body := &UpdateRequestBody{
		Name:               p.Name,
		LegalName:          p.LegalName,
		DisplayName:        p.DisplayName,
		TaxID:              p.TaxID,
		RegistrationNumber: p.RegistrationNumber,
		IncorporationDate:  p.IncorporationDate,
		Jurisdiction:       p.Jurisdiction,
		Description:        p.Description,
		Website:            p.Website,
		Industry:           p.Industry,
		EmployeeCount:      p.EmployeeCount,
		ParentID:           p.ParentID,
	}
	if p.OrganizationType != nil {
		organizationType := string(*p.OrganizationType)
		body.OrganizationType = &organizationType
	}
	if p.Status != nil {
		status := string(*p.Status)
		body.Status = &status
	}
	if p.Addresses != nil {
		body.Addresses = make([]*AddressInfoRequestBody, len(p.Addresses))
		for i, val := range p.Addresses {
			body.Addresses[i] = marshalOrganizationAddressInfoToAddressInfoRequestBody(val)
		}
	}
	if p.Contacts != nil {
		body.Contacts = make([]*ContactInfoRequestBody, len(p.Contacts))
		for i, val := range p.Contacts {
			body.Contacts[i] = marshalOrganizationContactInfoToContactInfoRequestBody(val)
		}
	}
	if p.Settings != nil {
		body.Settings = marshalOrganizationOrganizationSettingsToOrganizationSettingsRequestBody(p.Settings)
	}
	return body
}

