func ValidateAddressInfoRequestBody(body *AddressInfoRequestBody) (err error) {
	if !(body.Type == "HEADQUARTERS" || body.Type == "BRANCH" || body.Type == "BILLING" || body.Type == "SHIPPING" || body.Type == "MAILING" || body.Type == "WAREHOUSE") {
		err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.type", body.Type, []any{"HEADQUARTERS", "BRANCH", "BILLING", "SHIPPING", "MAILING", "WAREHOUSE"}))
	}
	if utf8.RuneCountInString(body.StreetAddress1) > 200 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.street_address_1", body.StreetAddress1, utf8.RuneCountInString(body.StreetAddress1), 200, false))
	}
	if body.StreetAddress2 != nil {
		if utf8.RuneCountInString(*body.StreetAddress2) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.street_address_2", *body.StreetAddress2, utf8.RuneCountInString(*body.StreetAddress2), 200, false))
		}
	}
	if utf8.RuneCountInString(body.City) > 100 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.city", body.City, utf8.RuneCountInString(body.City), 100, false))
	}
	if body.StateProvince != nil {
		if utf8.RuneCountInString(*body.StateProvince) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.state_province", *body.StateProvince, utf8.RuneCountInString(*body.StateProvince), 100, false))
		}
	}
	if body.PostalCode != nil {
		if utf8.RuneCountInString(*body.PostalCode) > 20 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.postal_code", *body.PostalCode, utf8.RuneCountInString(*body.PostalCode), 20, false))
		}
	}
	if utf8.RuneCountInString(body.Country) > 100 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.country", body.Country, utf8.RuneCountInString(body.Country), 100, false))
	}
	if body.CountryCode != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.country_code", *body.CountryCode, "^[A-Z]{2}$"))
	}
	return
}

